const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const THEMES = { blue: '#2563eb', green: '#16a34a', red: '#dc2626', amber: '#d97706' };
// rows = [[label, valueHtml], ...]   (valueHtml must already be escaped with esc())
function emailHtml(o) {
  const c = THEMES[o.theme || 'blue'];
  const rows = (o.rows || []).filter(r => r && r[1] !== '' && r[1] != null).map(r =>
    `<tr><td style="padding:9px 14px 9px 0;color:#64748b;font-size:13px;white-space:nowrap;vertical-align:top">${r[0]}</td><td style="padding:9px 0;color:#0f172a;font-size:15px;font-weight:600">${r[1]}</td></tr>`).join('');
  const box = rows ? `<tr><td style="padding:20px 32px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px"><tr><td style="padding:8px 20px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rows}</table></td></tr></table></td></tr>` : '';
  const btn = o.button ? `<tr><td style="padding:24px 32px 0"><a href="${esc(o.button.url)}" style="display:inline-block;background:${c};color:#ffffff;text-decoration:none;font-weight:600;font-size:15px;padding:13px 26px;border-radius:10px">${esc(o.button.label)}</a></td></tr>` : '';
  const note = o.note ? `<tr><td style="padding:20px 32px 0;font-size:13px;line-height:1.6;color:#64748b">${o.note}</td></tr>` : '';
  return `<div style="margin:0;padding:24px 12px;background:#eef2f7;font-family:Inter,'Segoe UI',Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto"><tr><td>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden">
<tr><td style="background:${c};height:6px;line-height:6px;font-size:0">&nbsp;</td></tr>
<tr><td style="padding:28px 32px 0"><div style="font-size:12px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;color:${c}">${esc(o.business)}</div>
<h1 style="margin:10px 0 0;font-size:24px;line-height:1.3;color:#0f172a">${o.icon || ''} ${esc(o.title)}</h1></td></tr>
<tr><td style="padding:12px 32px 0;font-size:15px;line-height:1.7;color:#334155">${o.intro || ''}</td></tr>
${box}${btn}${note}
<tr><td style="padding:28px 32px"><div style="border-top:1px solid #e2e8f0;padding-top:16px;font-size:12px;color:#94a3b8">${esc(o.business)}</div></td></tr>
</table></td></tr></table></div>`;
}
const errText = e => typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e || ''));
const asDate = v => {
  if (v === undefined || v === null || v === '') return null;
  const d = /^\d+$/.test(String(v)) ? DateTime.fromMillis(Number(v)) : DateTime.fromISO(String(v));
  return d.isValid ? d : null;
};

const pad = n => String(n).padStart(2, '0');
// The sheet keeps dates and times as text. If someone retypes a cell, Google may turn it into a number: handle both.
const dStr = v => {
  if (typeof v === 'number') return DateTime.fromMillis(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000, { zone: 'utc' }).toFormat('yyyy-MM-dd');
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m ? `${m[1]}-${pad(m[2])}-${pad(m[3])}` : s;
};
const tStr = v => {
  if (typeof v === 'number') { const mins = Math.round((v % 1) * 1440); return `${pad(Math.floor(mins / 60) % 24)}:${pad(mins % 60)}`; }
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})/);
  return m ? `${pad(m[1])}:${m[2]}` : s;
};
const startOf = (r, zone) => DateTime.fromFormat(`${dStr(r['Date'])} ${tStr(r['Start Time'])}`, 'yyyy-MM-dd HH:mm', { zone });
const endOf = (r, zone, start) => {
  const e = DateTime.fromFormat(`${dStr(r['Date'])} ${tStr(r['End Time'])}`, 'yyyy-MM-dd HH:mm', { zone });
  return (e.isValid && start.isValid && e > start) ? e : start.plus({ minutes: Number(r['Duration (min)']) || 60 });
};
// Reads the items coming from the Google Sheets node and checks them
const readBookings = items => {
  const readError = items.find(r => r && r.error);
  if (readError) throw new Error('Google Sheets read failed: ' + String(errText(readError.error)).slice(0, 300));
  const hasRows = items.some(r => r && r.row_number !== undefined);
  if (hasRows && !items.some(r => r && r['Booking ID'] !== undefined && r['Email'] !== undefined && r['Status'] !== undefined)) throw new Error('The header row of the Bookings sheet was changed.');
  return items.filter(r => r && r['Booking ID'] !== undefined && String(r['Booking ID']).trim() !== '');
};

// ====== SETTINGS ======
// Each reminder is sent ONCE, when the appointment is between minMin and maxMin minutes away.
const STAGES = [
  { key: '24h', minMin: 21 * 60, maxMin: 24 * 60 },   // day before (3h grace in case n8n was down)
  { key: '1h',  minMin: 0,       maxMin: 60 }         // starting soon
];
// ======================
const cfg = $('Config').first().json;
const zone = cfg.timezone;
const rows = readBookings($input.all().map(i => i.json));
const now = DateTime.now().setZone(zone);
const out = [];
for (const r of rows) {
  if (String(r['Status'] || '').trim().toLowerCase() !== 'booked') continue;
  const email = String(r['Email'] || '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) continue;
  const start = startOf(r, zone);
  if (!start.isValid) continue;
  const mins = start.diff(now, 'minutes').minutes;
  const sent = String(r['Reminder Sent'] || '').split(',').map(x => x.trim()).filter(Boolean);
  const stage = STAGES.find(s => mins > s.minMin && mins <= s.maxMin && !sent.includes(s.key));
  if (!stage) continue;

  const time = start.toFormat('HH:mm');
  const dateText = start.toFormat('cccc, d LLLL yyyy');
  const dayWord = start.hasSame(now, 'day') ? 'today' : 'tomorrow';
  const first = esc(String(r['Client Name'] || 'there').split(' ')[0]);
  const is24 = stage.key === '24h';
  const html = emailHtml({
    business: cfg.businessName, theme: is24 ? 'blue' : 'green', icon: is24 ? '⏰' : '📍',
    title: is24 ? 'Appointment reminder' : 'Your appointment is almost here',
    intro: `Hi ${first},<br>${is24 ? `This is a friendly reminder about your appointment ${dayWord}.` : 'Your appointment starts soon. We are ready for you!'}`,
    rows: [['Service', esc(r['Service'])], ['Date', esc(dateText)], ['Time', esc(time)],
           ['Booking ID', esc(r['Booking ID'])], ['Where', esc(cfg.locationText)]],
    button: { label: 'Change or cancel my booking', url: cfg.formUrl },
    note: 'To change or cancel, open the booking form and enter the same email address you used to book.'
  });
  out.push({ json: {
    bookingId: String(r['Booking ID']).trim(), email, stage: stage.key,
    subject: is24 ? `Reminder: your appointment ${dayWord} at ${time}` : `Starting soon: your appointment at ${time}`,
    html, remindersSentNew: sent.concat(stage.key).join(',')
  }});
}
return out;
